import{LEVELS,fresh,unlocked,record,finish,recommend,restore}from'./engine.mjs';
import{CHARACTERS as C,QUESTIONS as Q,DIAGNOSTIC}from'./content.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',learn:'M3 4h7q2 0 2 2v15q-2-2-9-2Z M21 4h-7q-2 0-2 2v15q2-2 9-2Z',review:'M4 8a8 8 0 1 1-1 7 M4 3v5h5',profile:'M8 7a4 4 0 1 0 8 0 4 4 0 1 0-8 0 M4 21v-2a8 8 0 0 1 16 0v2',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',arrow:'M5 12h14 M13 6l6 6-6 6',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6Z M8 10V6a4 4 0 0 1 8 0v4',leaf:'M19 3C3 2 1 15 8 19c7 4 15-3 11-16Z M6 21 17 6',close:'m6 6 12 12 M6 18 18 6',back:'M19 12H5 M11 6l-6 6 6 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.leaf}"/></svg>`;
let state=fresh(),storageOK=true;try{const raw=localStorage.getItem('reading-paths-v1');if(raw)state=restore(raw);}catch{storageOK=false;}
let mode='guided',filter='all',search='',step=0,reading=0,quiz=null;
const save=()=>{try{localStorage.setItem('reading-paths-v1',JSON.stringify(state));}catch{storageOK=false;toast('Storage is unavailable. Export your progress before closing this page.');}applyPrefs();};
function applyPrefs(){document.documentElement.dataset.size=state.preferences.size;document.documentElement.dataset.motion=state.preferences.motion;}
applyPrefs();
const phon=r=>state.preferences.notation==='none'?'':state.preferences.notation==='both'?`${esc(r.pinyin)} · ${esc(r.zhuyin)}`:esc(r[state.preferences.notation]);
const rawPhon=r=>state.preferences.notation==='none'?esc(r.pinyin):phon(r);
const questions=id=>Q.filter(q=>q.characterId===id),complete=()=>Object.values(state.lessons).filter(l=>l.passed).length;
const outstanding=()=>Object.values(state.mistakes).filter(m=>m.correctStreak<2);
const nextChar=()=>C.find(c=>questions(c.id).length&&unlocked(state,c.level)&&!state.lessons[c.id]?.passed)||C.find(c=>questions(c.id).length&&unlocked(state,c.level))||C[0];
const stageReady=l=>C.filter(c=>c.level===l&&questions(c.id).length);
const route=()=>location.hash.slice(1).split('/').filter(Boolean);
function go(path){if(location.hash===`#/${path}`)render();else location.hash=`/${path}`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function shell(body,active='home',crumb='Your learning space'){
 const nav=[['home','Home'],['learn','Learn'],['review','Review'],['profile','Profile']];
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#/home"><span class="brand-mark" lang="zh-Hant">字</span><span>Reading Paths<small>一字多讀</small></span></a><nav class="nav" aria-label="Main navigation">${nav.map(([id,label])=>`<a href="#/${id}" ${active===id?'aria-current="page"':''} class="${active===id?'active':''}">${icon(id)}<span>${label}</span>${id==='review'&&outstanding().length?`<b class="count">${outstanding().length}</b>`:''}</a>`).join('')}</nav><div class="sidebar-foot"><span class="seed">✳</span><b>One character.<br>More ways to understand.</b><p style="margin-top:12px">Traditional Chinese<br>TBCL × COCT</p></div></aside><div class="main-shell"><header class="topbar"><span class="crumb">${crumb}</span><div class="top-actions"><span class="proto">Working prototype</span><button class="text-btn" data-action="settings" aria-label="Open display preferences">${icon('settings')}<span>Display</span></button><a class="avatar" href="#/profile" aria-label="Your profile">${esc(state.name.slice(0,1).toUpperCase())}</a></div></header><main id="main" tabindex="-1">${body}<footer class="footer"><span>Reading Paths · 一字多讀<br>Small steps. Meaningful connections.</span><span>Sample lessons · Curriculum review in progress<br>${storageOK?'Progress saved on this browser':'Browser storage unavailable · export a backup'}</span></footer></main></div></div>`;
}
function stages(){return`<div class="path">${LEVELS.map(l=>{let open=unlocked(state,l),pass=state.stagePasses.includes(l);return`<button class="stage ${l===state.start?'current':''} ${!open&&mode==='guided'?'locked':''}" data-stage="${l}" aria-label="TBCL ${l}, ${pass?'review passed':open?'available':'guided path locked; challenge available'}"><span class="eyebrow">TBCL</span><span class="stage-state">${icon(pass?'check':!open&&mode==='guided'?'lock':'leaf')}</span><span class="stage-num">${l}</span><small>${pass?'Review passed':mode==='explore'?'Explore freely':open?'Open to learn':'Challenge to unlock'}</small></button>`;}).join('')}</div>`;}
function home(){let c=nextChar();shell(`<div class="welcome"><div><span class="eyebrow">Your Chinese, one connection at a time</span><h1>Welcome${state.name==='Learner'?'':`, ${esc(state.name)}`}.</h1></div><span class="date-note">Learn at your own pace.</span></div><section class="hero"><div class="hero-copy"><span class="eyebrow">Same character. A new perspective.</span><h2>A small shift.<br>A whole new meaning.</h2><p>Discover how a character changes its sound across words. Connect the reading to the meaning, then make it yours.</p><button class="btn" data-lesson="${c.id}">${complete()?'Continue learning':'Begin a lesson'} ${icon('arrow')}</button></div><div class="hero-art" aria-label="好 has the readings hǎo and hào"><div class="orbit"></div><span class="reading-tag a">${phon(C[0].readings[0])}</span><span class="hero-character" lang="zh-Hant">好</span><span class="reading-tag b">${phon(C[0].readings[1])}</span><span class="art-caption">One shape · Different meanings</span></div></section><div class="stats"><div class="stat"><span class="stat-icon">${icon('learn')}</span><div><strong>${complete()}</strong><small>Character checks passed</small></div></div><div class="stat"><span class="stat-icon">${icon('review')}</span><div><strong>${outstanding().length}</strong><small>Connections to revisit</small></div></div><div class="stat"><span class="stat-icon">${icon('leaf')}</span><div><strong>${state.start}</strong><small>Your chosen starting stage</small></div></div></div><section><div class="section-head"><div><h2>Your learning path</h2><p>A little structure, with room to explore.</p></div><div class="tabs" aria-label="Learning mode"><button data-mode="guided" class="${mode==='guided'?'active':''}">Guided path</button><button data-mode="explore" class="${mode==='explore'?'active':''}">Free explore</button></div></div>${stages()}</section><div class="dash-lower"><section><div class="section-head"><h2>Up next</h2><button class="text-btn" data-action="all-lessons">All characters ${icon('arrow')}</button></div><button class="preview-lesson" style="width:100%;text-align:left" data-lesson="${c.id}"><span class="char-tile" lang="zh-Hant">${c.char}</span><span><span class="badge">TBCL ${c.level} · SAMPLE LESSON</span><h3>${c.title}</h3><p>${c.readings.length} reading connections · 5 questions</p></span>${icon('arrow')}</button></section><section><div class="section-head"><h2>Make it comfortable</h2></div><div class="note-card"><span class="eyebrow">A space that fits you</span><p>Choose your text size and switch between Pinyin and Zhuyin whenever you like.</p><button class="text-btn" data-action="settings">Adjust your display ${icon('arrow')}</button></div></section></div>`);}
function card(c){const locked=mode==='guided'&&!unlocked(state,c.level);return`<button class="lesson-card" data-lesson="${c.id}"><span><span class="badge">TBCL ${c.level}</span>${state.lessons[c.id]?.passed?'<span class="badge" style="float:right">✓ Check passed</span>':''}</span><span class="big-char" lang="zh-Hant">${c.char}</span><div class="reading-pair">${c.readings.map(phon).filter(Boolean).join(' / ')}</div><h3>${c.title}</h3><span class="card-bottom"><span>${locked?'Guided path locked':questions(c.id).length?'Sample lesson':'Preview · content pending'}</span>${icon(locked?'lock':'arrow')}</span></button>`;}
function learn(){const list=C.filter(c=>(filter==='all'||c.level===filter)&&(!search||`${c.char} ${c.title} ${c.readings.map(r=>r.pinyin).join(' ')}`.toLowerCase().includes(search.toLowerCase())));shell(`<div class="page-intro"><div class="eyebrow">The character collection</div><h1>Follow your curiosity.</h1><p>Start with a character. Explore its readings, meet its words, and find it in real language.</p></div><div class="tabs"><button data-mode="guided" class="${mode==='guided'?'active':''}">Guided path</button><button data-mode="explore" class="${mode==='explore'?'active':''}">Free explore</button></div><div class="toolbar"><div class="filters">${['all',...LEVELS].map(l=>`<button class="pill ${filter===l?'active':''}" data-filter="${l}">${l==='all'?'All stages':l}</button>`).join('')}</div><input class="search" aria-label="Search sample lessons" id="search" placeholder="Search a character or reading" value="${esc(search)}"></div><div class="lesson-grid">${list.map(card).join('')}</div>${!list.length?`<div class="empty"><h3>No sample lessons here yet.</h3><p>This stage is waiting for reviewed content. You can explore another stage while your progress stays saved.</p><button class="btn secondary" data-filter="all">See all sample lessons</button></div>`:''}<div class="callout">This prototype includes 5 character previews and 4 five-question checks. The complete character collection is being checked against dictionary readings independently of word availability.</div>`,'learn','Learn / Character collection');}
function stagePage(l){let list=C.filter(c=>c.level===l),open=unlocked(state,l);shell(`<a href="#/home" class="back">${icon('back')} Back to your path</a><div class="page-intro"><div class="eyebrow">Your learning path</div><h1>TBCL ${esc(l)}</h1><p>${open||mode==='explore'?'Choose a character, or check what you already know.':'This stage is locked in your guided path. You can still explore freely, or pass the previous stage review to unlock it.'}</p></div><div class="button-row">${!open?'<button class="btn secondary" data-action="explore-stage" data-level="'+l+'">Explore this stage freely</button>':''}<button class="btn" data-action="stage-quiz" data-level="${open?l:LEVELS[Math.max(0,LEVELS.indexOf(l)-1)]}">${open?'Try this stage review':'Challenge the previous stage review'} ${icon('arrow')}</button></div><div class="callout">Stage reviews use the available sample questions only. Passing unlocks the next stage in this prototype; it does not certify a TBCL level.</div><div class="lesson-grid">${list.map(card).join('')}</div>${!list.length?'<div class="empty"><h3>Lessons are on their way.</h3><p>The shell is ready for reviewed character content at this stage.</p></div>':''}`,'learn',`Learn / TBCL ${esc(l)}`);}
function lesson(id){const c=C.find(c=>c.id===id);if(!c)return go('learn');if(mode==='guided'&&!unlocked(state,c.level))return stagePage(c.level);reading=Math.min(reading,c.readings.length-1);const r=c.readings[reading];let content='';if(step===0)content=`<span class="eyebrow">Notice the reading</span><h2>Same character, different connections.</h2><p class="muted" style="margin-top:12px">Select each reading. Notice how its meaning changes.</p><div class="reading-focus">${phon(r)||'<span class="zh" lang="zh-Hant">'+c.char+'</span>'}</div><p class="meaning">${esc(r.meaning)}</p><div class="callout">${esc(c.hint)}</div>${r.note?`<p class="muted" style="font-size:.82rem">${esc(r.note)}</p>`:''}`;
 if(step===1)content=`<span class="eyebrow">Build a connection</span><h2>Meet the words.</h2><p class="muted" style="margin:12px 0 22px">These words use ${esc(c.char)} as ${rawPhon(r)}. Word levels can be higher than the character level.</p><div class="word-list">${r.words.map(w=>`<div class="word-row"><div><div class="zh" lang="zh-Hant">${esc(w.text)}</div><div class="phonetics">${phon(w)}</div><div class="gloss">${esc(w.gloss)}</div><details class="source"><summary>Word source</summary>NAER TBCL wordlist · worksheet row ${w.source.row}</details></div><span class="badge">WORD ${w.level}</span></div>`).join('')||`<div class="empty"><h3>A reading worth keeping.</h3><p>${esc(r.note||'Vocabulary for this reading is awaiting review.')}</p></div>`}</div>`;
 if(step===2)content=`<span class="eyebrow">Find it in real language</span><h2>From words to a sentence.</h2>${r.sentences.map(s=>`<article class="sentence-card"><span class="badge">CORPUS ORIGINAL · REVIEW CANDIDATE</span><p class="zh" lang="zh-Hant" style="margin-top:22px">${esc(s.text).replace(esc(s.target),`<mark>${esc(s.target)}</mark>`)}</p><div class="source">${esc(s.source.corpus)} · text ${esc(s.source.textId)}<br>Observed query ${s.source.queryId}, result ${s.source.rank}.<br><a href="${s.source.url}" target="_blank" rel="noopener">Open the COCT corpus ↗</a><br>${esc(s.source.status)}. Original wording retained.</div></article>`).join('')||'<div class="empty" style="margin-top:22px"><h3>A real example is on its way.</h3><p>A COCT sentence for this reading is awaiting selection. You can keep exploring the words or try the word-reading check.</p></div>'}`;
 shell(`<a href="#/learn" class="back">${icon('back')} Back to characters</a><div class="lesson-layout"><aside class="lesson-identity"><span class="badge">CHARACTER · TBCL ${c.level}</span><div class="display-char" lang="zh-Hant">${c.char}</div><h2>${c.title}</h2><p>${c.readings.length} sample readings<br>Character → words → sentences</p>${c.dictionary?`<a class="source" href="${c.dictionary}" target="_blank" rel="noopener">Dictionary reading reference ↗</a>`:''}</aside><section><nav class="steps" aria-label="Lesson steps">${['Character','Words','Sentences'].map((v,i)=>`<button data-step="${i}" class="${step===i?'active':''}" ${step===i?'aria-current="step"':''}><span class="step-num">${i+1}</span>${v}</button>`).join('')}</nav><div class="reading-options" aria-label="Choose a reading">${c.readings.map((v,i)=>`<button class="reading-btn ${reading===i?'active':''}" data-reading="${i}" aria-pressed="${reading===i}"><strong>${phon(v)||`Reading ${i+1}`}</strong><small>${esc(v.meaning)}</small></button>`).join('')}</div><div id="lesson-content" style="animation:arrive .3s">${content}</div>${c.note?`<p class="source">${esc(c.note)}</p>`:''}<div class="lesson-actions">${step>0?'<button class="text-btn" data-action="previous-step">'+icon('back')+' Back</button>':'<span class="muted" style="font-size:.75rem">Try both readings before moving on.</span>'}${step<2?`<button class="btn" data-action="next-step">${step===0?'Explore the words':'See a sentence'} ${icon('arrow')}</button>`:questions(id).length?`<button class="btn" data-action="lesson-quiz" data-id="${id}">Try the 5-question check ${icon('arrow')}</button>`:'<span class="badge">Quiz awaiting reviewed content</span>'}</div></section></div>`,'learn',`Learn / ${c.char} / ${['Character','Words','Sentences'][step]}`);}
function onboarding(){shell(`<section class="onboard"><div class="onboard-art" lang="zh-Hant">初</div><span class="eyebrow">A good place to begin</span><h1 style="margin-top:14px">Make this path your own.</h1><p class="muted" style="margin-top:20px">A short check can suggest a starting stage. You can change it at any time, or explore any character freely.</p><div class="onboard-choices"><div class="onboard-card"><h3>Find a starting point</h3><p>Try 6 sample questions about word readings. About 2 minutes, with no timer.</p><button class="btn" data-action="diagnostic">Try the starting check ${icon('arrow')}</button></div><div class="onboard-card"><h3>Choose your own start</h3><p>Already have a preference? Pick a stage and begin. You can return to the check later.</p><label class="field"><span>Starting stage</span><select id="start-choice">${LEVELS.map(l=>`<option value="${l}">TBCL ${l}</option>`).join('')}</select></label><button class="btn secondary" data-action="skip-onboarding">Start here ${icon('arrow')}</button></div></div><p class="source">This prototype check recommends a starting point among its sample stages (1, 1*, 2). It is not an official TBCL assessment and does not measure your overall Chinese proficiency.</p></section>`,'home','Welcome / Choose a starting point');}
function startQuiz(type,id){let qs=type==='diagnostic'?DIAGNOSTIC:type==='lesson'?questions(id):type==='stage'?Q.filter(q=>C.find(c=>c.id===q.characterId).level===id):id?[Q.find(q=>q.id===id)].filter(Boolean):outstanding().filter(m=>m.due<=Date.now()).map(m=>Q.find(q=>q.id===m.questionId)).filter(Boolean);if(!qs.length){toast(type==='stage'?'This stage review is waiting for reviewed questions.':'No questions are due right now.');return;}quiz={type,id,questions:qs,index:0,score:0,answered:false,chosen:null,done:false};go('quiz');}
function quizPage(){if(!quiz)return go('home');const t=quiz;if(t.done)return result();const q=t.questions[t.index],c=C.find(c=>c.id===q.characterId);shell(`<section class="quiz-wrap"><div class="quiz-header"><span>${t.type==='diagnostic'?'Starting point check':t.type==='review'?'A connection to revisit':t.type==='stage'?`TBCL ${t.id} · Sample stage review`:`${c.char} · Character check`}</span><button class="text-btn" data-action="exit-quiz">Save & leave ×</button></div><div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="${t.questions.length}" aria-valuenow="${t.index}"><span style="width:${100*t.index/t.questions.length}%"></span></div><div class="eyebrow">Question ${t.index+1} of ${t.questions.length}</div><h2 class="quiz-question" style="margin-top:17px">How is <span lang="zh-Hant">${c.char}</span> read in this word?</h2><div class="quiz-word" lang="zh-Hant">${esc(q.word)}</div><div class="answers">${c.readings.map((r,i)=>`<button class="answer ${t.answered&&r.id===q.readingId?'correct':t.answered&&r.id===t.chosen?'incorrect':''}" data-answer="${r.id}" ${t.answered?'disabled':''}><span style="font-size:.7rem;display:block;color:var(--muted);margin-bottom:7px">${String.fromCharCode(65+i)}</span>${rawPhon(r)}${t.answered&&r.id===q.readingId?' ✓':''}</button>`).join('')}</div>${state.preferences.notation==='none'?'<p class="source">Reading choices are shown for this question. Lesson pronunciation hints remain hidden.</p>':''}${t.answered?`<div class="feedback ${t.chosen!==q.readingId?'wrong':''}" role="status"><h3>${t.chosen===q.readingId?'That connection fits.':'A useful one to revisit.'}</h3><p>${esc(q.explanation)} ${t.type==='diagnostic'?'':t.chosen!==q.readingId?'Saved in Review so you can practise it again.':''}</p></div><div style="text-align:right;margin-top:22px"><button class="btn" data-action="next-question" id="continue-question">${t.index+1===t.questions.length?'See your result':'Next question'} ${icon('arrow')}</button></div>`:'<p class="source">Choose a reading. Take your time.</p>'}</section>`,'learn','Practice / Word readings');if(t.answered)$('#continue-question')?.focus({preventScroll:true});}
function result(){const t=quiz,pass=t.score/t.questions.length>=.8;let body='';if(t.type==='diagnostic'){let l=recommend(t.score,t.questions.length);body=`<span class="eyebrow">A starting suggestion, not a label</span><h1>Start where it feels right.</h1><div class="result-score">${l}</div><h2>Suggested sample stage · TBCL ${l}</h2><p>You answered ${t.score} of ${t.questions.length} sample questions correctly. This suggests a starting place for these lessons; it is not a TBCL proficiency result.</p><label class="field" style="max-width:260px;margin:24px auto"><span>Your starting stage</span><select id="result-start">${LEVELS.map(x=>`<option value="${x}" ${x===l?'selected':''}>TBCL ${x}</option>`).join('')}</select></label><button class="btn" data-action="accept-start">Make this my starting point ${icon('arrow')}</button><p class="source">You can change this in Profile or use Free explore at any time.</p>`;}else{body=`<span class="eyebrow">${t.type==='review'?'Keep the connection growing':pass?'A step forward':'Progress includes coming back'}</span><h1>${t.type==='review'?'Practice saved.':pass?'Nicely connected.':'Let’s revisit a few.'}</h1><div class="result-score">${t.score}<span style="font-size:2rem;color:var(--muted)"> / ${t.questions.length}</span></div><p>${t.type==='review'?'Correctly revisited items return after a day, then after three days. Two correct revisits move an item out of your active review list.':t.type==='stage'?pass?'Sample stage review passed. The next stage is now open in your guided path.':'Aim for 80% to pass the stage review. Your missed connections are saved in Review.':pass?'Character check passed. Your progress is shared with your guided path and Free explore.':'Aim for 4 out of 5 to pass this character check. Revisit the readings and try again when you’re ready.'}</p><button class="btn" data-action="result-continue">${t.type==='lesson'?'Back to the character':'Back to your path'} ${icon('arrow')}</button><a class="btn secondary" href="#/review">See your review list</a>${t.type!=='review'?'<button class="text-btn" data-action="retry">Try this check again</button>':''}`;}shell(`<section class="quiz-wrap result">${body}</section>`,'learn','Practice / Result');}
function review(){const items=Object.values(state.mistakes).sort((a,b)=>a.due-b.due),due=items.filter(m=>m.due<=Date.now()&&m.correctStreak<2);shell(`<div class="page-intro"><div class="eyebrow">Your review space</div><h1>A mistake is a useful clue.</h1><p>Come back to the exact word and reading that needs another connection. Nothing here resets your learning progress.</p></div>${items.length?`<div class="toolbar"><p class="muted">${due.length} due now · ${outstanding().length} still practising</p><button class="btn" data-action="review-quiz" ${!due.length?'disabled':''}>Review due connections ${icon('arrow')}</button></div><div class="review-list">${items.map(m=>{let q=Q.find(q=>q.id===m.questionId);if(!q)return'';let c=C.find(c=>c.id===q.characterId),r=c.readings.find(r=>r.id===q.readingId);return`<div class="review-row"><div><div class="zh" lang="zh-Hant">${esc(q.word)}</div><div class="phonetics">${phon(r)}</div><small>${m.wrongCount} missed attempt${m.wrongCount===1?'':'s'} · ${m.correctStreak>=2?'Revisited twice':m.due>Date.now()?`Next revisit ${new Date(m.due).toLocaleDateString('en-US',{month:'short',day:'numeric'})}`:'Ready to revisit'}</small></div><div class="button-row"><button class="btn secondary small" data-lesson="${c.id}">Relearn</button><button class="text-btn" data-review-id="${q.id}">Practise ${icon('arrow')}</button></div></div>`;}).join('')}</div><p class="source">Prototype review repeats the original question. New transfer questions and long-term mastery criteria will be added with reviewed content.</p>`:'<div class="empty"><div class="onboard-art" style="margin:0 auto 20px">↺</div><h2>A clear space for now.</h2><p>When a practice question trips you up, its word and reading will appear here. You can return to the lesson or practise it again.</p><a class="btn" href="#/learn">Explore a character '+icon('arrow')+'</a></div>'}`,'review','Review / Your connections');}
function profile(){let attempts=state.attempts.filter(a=>a.mode!=='diagnostic'),accuracy=attempts.length?Math.round(attempts.filter(a=>a.correct).length/attempts.length*100):null;shell(`<div class="page-intro"><div class="eyebrow">Your learning profile</div><h1>A path that belongs to you.</h1><p>Your name, preferences, and progress stay in this browser. Export a backup to move them to another device or website.</p></div><div class="profile-grid"><section class="panel"><h2>Your learning setup</h2><form id="profile-form"><div class="field"><label for="learner-name">Preferred name</label><input id="learner-name" maxlength="60" value="${esc(state.name)}" autocomplete="nickname"></div><div class="field"><label for="profile-start">Chosen starting stage</label><select id="profile-start">${LEVELS.map(l=>`<option value="${l}" ${l===state.start?'selected':''}>TBCL ${l}</option>`).join('')}</select></div><p class="source">Starting at a later stage opens earlier stages too. Review badges are earned separately.</p><button class="btn" style="margin-top:20px" type="submit">Save profile</button></form><button class="text-btn" style="margin-top:15px" data-action="diagnostic">Retake the starting check ${icon('arrow')}</button></section><section class="panel"><h2>Your progress, so far</h2><div class="history">${complete()} character checks passed<br>${state.stagePasses.length} sample stage reviews passed<br>${attempts.length} practice answers · ${accuracy===null?'No accuracy data yet':accuracy+'% correct'}<br>${outstanding().length} connections still practising</div><div class="callout">Saved on this device and browser only. Clearing website data removes the local copy. This version has no cloud account or cross-device sync.</div><h3>Keep a copy</h3><p class="source" style="margin:10px 0 17px">A backup includes your profile, preferences, answers, and review list. Import replaces the current local progress after confirmation.</p><div class="button-row"><button class="btn secondary small" data-action="export">Export backup</button><button class="btn secondary small" data-action="import">Import backup</button></div><input id="backup-file" type="file" accept="application/json,.json" hidden></section></div>`,'profile','Profile / Your learning setup');}
function settings(){const d=$('#settings');d.className='settings-dialog';d.innerHTML=`<div class="dialog-head"><h2 id="settings-title">Make yourself comfortable.</h2><button class="icon-btn" data-action="close-settings" aria-label="Close display preferences">${icon('close')}</button></div><p class="setting-note">Your choices apply across the learning space.</p><div class="setting-group"><h3>Text size</h3><div class="button-row">${['small','medium','large'].map(s=>`<button class="pill" data-pref="size" data-value="${s}" aria-pressed="${state.preferences.size===s}">${s[0].toUpperCase()+s.slice(1)}</button>`).join('')}</div></div><div class="setting-group"><h3>Pronunciation hints</h3><div class="button-row">${[['pinyin','Pinyin'],['zhuyin','Zhuyin 注音'],['both','Both'],['none','Hide hints']].map(([s,label])=>`<button class="pill" data-pref="notation" data-value="${s}" aria-pressed="${state.preferences.notation===s}">${label}</button>`).join('')}</div><p class="setting-note">Reading choices stay visible when a question asks you to choose a pronunciation.</p></div><div class="setting-group"><h3>Motion</h3><div class="button-row">${[['system','Follow device setting'],['reduced','Reduce motion']].map(([s,label])=>`<button class="pill" data-pref="motion" data-value="${s}" aria-pressed="${state.preferences.motion===s}">${label}</button>`).join('')}</div></div><div class="word-row"><div><div class="zh" lang="zh-Hant">快樂</div><div class="phonetics">${phon(C[2].readings[0].words[0])}</div><span class="gloss">Preview · happy</span></div></div><button class="btn" style="margin-top:24px;width:100%" data-action="close-settings">Done</button>`;if(!d.open)d.showModal();}
function render(){const [page,id]=route();if(!state.onboarded&&page!=='quiz'){onboarding();return;}if(page==='learn')learn();else if(page==='stage'&&LEVELS.includes(id))stagePage(id);else if(page==='lesson')lesson(id);else if(page==='quiz')quizPage();else if(page==='review')review();else if(page==='profile')profile();else home();}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.pref){state.preferences[d.pref]=d.value;save();render();settings();return;}if(d.mode){mode=d.mode;render();return;}if(d.filter){filter=d.filter;render();return;}if(d.stage){go('stage/'+d.stage);return;}if(d.lesson){reading=0;step=0;go('lesson/'+d.lesson);return;}if(d.step!==undefined){step=Number(d.step);render();return;}if(d.reading!==undefined){reading=Number(d.reading);render();return;}if(d.reviewId){startQuiz('review',d.reviewId);return;}if(d.answer&&quiz&&!quiz.answered){let q=quiz.questions[quiz.index];quiz.chosen=d.answer;quiz.answered=true;if(d.answer===q.readingId)quiz.score++;if(quiz.type!=='diagnostic'){state=record(state,q,d.answer===q.readingId,quiz.type);save();}quizPage();return;}switch(d.action){case'settings':settings();break;case'close-settings':$('#settings').close();break;case'all-lessons':filter='all';go('learn');break;case'explore-stage':mode='explore';go('stage/'+d.level);break;case'next-step':step=Math.min(2,step+1);render();break;case'previous-step':step=Math.max(0,step-1);render();break;case'lesson-quiz':startQuiz('lesson',d.id);break;case'stage-quiz':startQuiz('stage',d.level);break;case'diagnostic':startQuiz('diagnostic');break;case'skip-onboarding':state.start=$('#start-choice').value;state.onboarded=true;save();go('home');break;case'accept-start':state.recommended=recommend(quiz.score,quiz.questions.length);state.start=$('#result-start').value;state.onboarded=true;save();go('home');break;case'exit-quiz':if(confirm('Leave this check? Answered practice questions are saved. This unfinished score will not count as a pass.')){quiz=null;go('home');}break;case'next-question':if(!quiz?.answered)return;if(++quiz.index>=quiz.questions.length){quiz.done=true;if(['lesson','stage'].includes(quiz.type)){state=finish(state,quiz.type,quiz.id,quiz.score,quiz.questions.length);save();}result();}else{quiz.answered=false;quiz.chosen=null;quizPage();}break;case'review-quiz':startQuiz('review');break;case'result-continue':if(quiz.type==='lesson'){step=0;reading=0;go('lesson/'+quiz.id);}else go('home');break;case'retry':startQuiz(quiz.type,quiz.id);break;case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='reading-paths-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup exported. Keep it somewhere safe.');break;}case'import':$('#backup-file').click();break;}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;let pos=e.target.selectionStart;learn();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();state.name=$('#learner-name').value.trim()||'Learner';state.start=$('#profile-start').value;save();profile();toast('Your profile is saved.');}});
document.addEventListener('change',async e=>{if(e.target.id==='backup-file'&&e.target.files[0]){try{let f=e.target.files[0];if(f.size>5000000)throw Error('This backup is too large.');let imported=restore(await f.text());if(confirm('Replace the learning progress currently stored in this browser with this backup?')){state=imported;save();render();toast('Your learning backup has been restored.');}}catch(err){toast(err.message||'Could not import this backup.');}}});
addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});});
render();
